const $=s=>document.querySelector(s);
const paths={hoje:'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3z"/>',agenda:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',mercado:'<path d="M3 3h2l3 12h11l3-9H6"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',financas:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18m-6 5h3"/>',planos:'<rect x="4" y="4" width="16" height="17" rx="3"/><path d="m8 10 2 2 5-5m-7 9h8"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="m15 5-7 7 7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pin:'<path d="M12 21s6-5.2 6-11a6 6 0 1 0-12 0c0 5.8 6 11 6 11Z"/><circle cx="12" cy="10" r="2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.planos}</svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const today=new Date(), iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`, base=iso(today),monthKey=base.slice(0,7);
const dateAt=n=>{let d=new Date(today);d.setDate(d.getDate()+n);return iso(d)};
const niceDate=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'});
const uid=()=>crypto.randomUUID();
const seed=()=>({marketCategories:['Hortifruti','Mercearia','Cuidados','Outros'],categories:['Casa','Mercado','Filho','Carro','Família'],items:[{id:'i1',name:'Banana',qty:'1 dúzia',sector:'Hortifruti',done:false},{id:'i2',name:'Leite integral',qty:'3 caixas',sector:'Mercearia',done:false},{id:'i3',name:'Fraldas',qty:'60 unidades',sector:'Cuidados',track:true,done:false},{id:'i4',name:'Tomate',qty:'500 g',sector:'Hortifruti',done:false},{id:'i5',name:'Café',qty:'1 pacote',sector:'Mercearia',done:true}],bills:[{id:'b1',name:'Condomínio',amount:68000,date:dateAt(2),paid:false,category:'Casa'},{id:'b2',name:'Internet',amount:11990,date:dateAt(4),paid:false,category:'Casa'},{id:'b3',name:'Mercado da semana',amount:34280,date:base,paid:true,payer:'Diego',category:'Mercado'},{id:'b4',name:'Sofá · 2/6',amount:35000,date:dateAt(7),paid:false,category:'Casa'}],tasks:[{id:'t1',name:'Pedir orçamento do vazamento',area:'Casa',owner:'Diego',done:false},{id:'t2',name:'Separar documentos da consulta',area:'Filho',owner:'Sem responsável',done:false}],products:[{id:'p1',name:'Fraldas',days:18,bought:dateAt(-14),history:[],cycles:3}],plans:[{id:'p01',name:'Resolver o vazamento',area:'Casa',detail:'Pedir orçamento ao encanador',status:'Em andamento',progress:25},{id:'p02',name:'Um sábado em família',area:'Família',detail:'Escolher um passeio e reservar a manhã',status:'Ideias',progress:0},{id:'p03',name:'Revisão do carro',area:'Carro',detail:'Comparar oficinas e datas',status:'Em andamento',progress:0}]});
const key='casa-prototype-v1';let state;try{state=JSON.parse(localStorage.getItem(key))||seed()}catch{state=seed()}
state.marketCategories=[...new Set([...(state.marketCategories||['Hortifruti','Mercearia','Cuidados','Outros']),...state.items.map(i=>i.sector).filter(Boolean),'Outros'])];
state.categories=[...new Set([...(state.categories||['Casa','Mercado','Filho','Carro','Família']),...state.bills.map(b=>b.category).filter(Boolean)])];
let tab='hoje',filter='Todos',planFilter='Todos',selectedDay=base,financeMonth=monthKey,financeFilter='Todos',toastTimer;
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Alterações somente nesta sessão. O armazenamento está indisponível.')}}
function toast(text,undo){clearTimeout(toastTimer);$('#toast').innerHTML=`<span>${esc(text)}</span>${undo?'<button id="undo">Desfazer</button>':''}`;$('#toast').classList.add('show');if(undo)$('#undo').onclick=()=>{undo();save();render();$('#toast').classList.remove('show')};toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),8000)}
function commit(fn,text){const previous=structuredClone(state);fn();save();render();if(text)toast(text,()=>state=previous)}
function openModal(title,body){$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="round" aria-label="Fechar" data-close>${icon('close')}</button></div>${body}`;$('#dialog').showModal();$('[data-close]').onclick=()=>$('#dialog').close()}
const heading=(title,desc,action='')=>{const pageIcon={Hoje:'hoje',Agenda:'agenda',Mercado:'mercado',Finanças:'financas',Planos:'planos'}[title];return `<div class="heading"><div><h1>${pageIcon?`<span class="heading-icon">${icon(pageIcon)}</span>`:''}${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`};
const button=(label,action)=>`<button class="primary" data-action="${action}">${icon('plus')}${label}</button>`;
const events=[{day:base,time:'08:00',title:'Café da manhã juntos',local:'Em casa',area:'Família'},{day:base,time:'10:30',title:'Passar no mercado',local:'Lista da semana',area:'Casa'},{day:base,time:'19:00',title:'Preparar a próxima semana',local:'Em casa',area:'Família'},{day:base,time:'16:00',title:'Passeio em família',local:'Praia da Costa',area:'Família'},{day:dateAt(1),time:'09:30',title:'Consulta do pequeno',local:'Consultório · exemplo',area:'Filho'},{day:dateAt(2),time:'18:00',title:'Organizar a semana',local:'Em casa',area:'Família'}];
events.sort((a,b)=>(a.day+a.time).localeCompare(b.day+b.time));
let googleEvents=[];
function billRow(b){return `<div class="row"><div class="icon-box">${icon(b.paid?'check':'financas')}</div><div class="row-content"><button class="expense-title" data-expense-edit="${b.id}">${esc(b.name)}</button><span class="row-meta">${b.paid?'Pago':'Vence'} ${niceDate(b.date)} · ${esc(b.category)}${b.paid?' · '+esc(b.payer||'Diego'):''}</span></div><span class="money">${money(b.amount)}</span>${!b.paid?`<button class="round" data-pay="${b.id}" aria-label="Marcar ${esc(b.name)} como pago">${icon('check')}</button>`:''}</div>`}
function taskRow(t){return `<div class="row"><label class="check-label"><input class="check" type="checkbox" ${t.done?'checked':''} data-task="${t.id}" aria-label="Concluir ${esc(t.name)}"></label><div class="row-content"><span class="row-title">${esc(t.name)}</span><span class="row-meta">${esc(t.area)} · ${esc(t.owner)}${t.due?' · Até '+niceDate(t.due):''}</span></div></div>`}
function home(){let unpaid=state.bills.filter(b=>!b.paid&&(b.type||'expense')==='expense'),count=state.items.filter(i=>!i.done).length;return heading('Hoje',today.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}))+`<div class="grid"><div class="stack">${todayEvents()}<section class="card"><div class="card-head"><h2>Tarefas</h2><button class="text-button" data-action="planos">Ver todos</button></div>${state.tasks.slice(0,3).map(taskRow).join('')}</section></div><div class="stack"><section class="card"><div class="card-head"><h2>Contas próximas</h2><span class="pill amber">${unpaid.length} pendentes</span></div>${unpaid.slice(0,2).map(billRow).join('')||'<p>Nenhuma conta pendente.</p>'}<button class="text-button" data-action="financas">Ver o mês completo →</button></section><section class="card"><div class="card-head"><h2>Mercado</h2>${icon('mercado')}</div><p>${count} itens na lista compartilhada.</p><button class="primary" data-action="mercado">Abrir lista</button></section></div></div>`}
function market(){const active=state.items.filter(i=>!i.done&&(filter==='Todos'||i.sector===filter)),done=state.items.filter(i=>i.done);const row=i=>`<div class="row ${i.done?'bought':''}"><label class="check-label"><input class="check" type="checkbox" ${i.done?'checked':''} data-item="${i.id}" aria-label="${i.done?'Desmarcar':'Comprar'} ${esc(i.name)}"></label><div class="row-content"><button class="item-edit" data-edit="${i.id}"><span class="row-title">${esc(i.name)}</span><span class="row-meta">${esc(i.qty||i.sector)}${i.track?' · Reposição ativa':''}</span></button></div>${icon('arrow')}</div>`;return heading('Mercado','')+`<form class="add-form" id="add-item"><input name="name" placeholder="Adicionar item" aria-label="Nome do item" maxlength="100" required autocomplete="off"><button class="primary" aria-label="Adicionar item">${icon('plus')}</button></form><div class="category-toolbar"><div class="chips">${['Todos',...state.marketCategories].map(f=>`<button class="chip ${filter===f?'selected':''}" data-filter="${esc(f)}">${esc(f)}</button>`).join('')}</div><button class="text-button" data-action="market-categories">Editar categorias</button></div><section class="card market-card">${active.map(row).join('')||'<div class="empty">Nenhum item pendente nesta seleção.</div>'}</section><div class="section-label"><h2>Comprados · ${done.length}</h2>${done.length?'<button class="text-button" data-action="clear">Limpar comprados</button>':''}</div><details><summary class="muted">Ver itens comprados</summary><section class="card market-card">${done.map(row).join('')}</section></details><div class="section-label"><h2>Reposição</h2></div><section class="card">${state.products.map(p=>`<div class="row"><div class="row-content"><button class="expense-title" data-product-edit="${p.id}">${esc(p.name)}</button><span class="row-meta">${p.days?`Duração estimada: ${p.days} dias · ${p.cycles||1} ciclos`:'Sem histórico de consumo'}${p.bought?`<br>Última compra: ${niceDate(p.bought)}`:''}</span></div><button class="chip" data-refill="${p.id}">Preciso comprar</button><button class="text-button" data-product-delete="${p.id}">Excluir</button></div>`).join('')||'<p>Ative o acompanhamento nos detalhes de um item.</p>'}</section>`}
function agenda(){
 const upcoming=events.filter(e=>e.day>=selectedDay);
 const days=[...new Set([selectedDay,...upcoming.map(e=>e.day)])];
 return heading('Agenda','')+`<div class="days">${Array.from({length:7},(_,n)=>{const d=new Date(today);d.setDate(d.getDate()+n);return `<button class="day ${selectedDay===iso(d)?'selected':''}" data-day="${iso(d)}" aria-label="Mostrar agenda a partir de ${niceDate(iso(d))}" aria-pressed="${selectedDay===iso(d)}">${d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}<strong>${d.getDate()}</strong></button>`}).join('')}</div><div class="agenda-days">${days.map(day=>`<section class="card"><div class="card-head"><h2>${day===base?'Hoje':day===dateAt(1)?'Amanhã':niceDate(day)}</h2><span class="muted">${niceDate(day)}</span></div>${agendaDay(upcoming.filter(e=>e.day===day))}</section>`).join('')}</div>`;
}
function finances(){let bills=state.bills.filter(b=>b.date.startsWith(financeMonth)),paid=bills.filter(b=>b.paid).reduce((n,b)=>n+b.amount,0),pending=bills.filter(b=>!b.paid).reduce((n,b)=>n+b.amount,0);return heading('Finanças','',button('Registrar','new-bill'))+`<div class="month-control"><button class="round" data-month="-1" aria-label="Mês anterior">${icon('back')}</button><strong>${new Date(financeMonth+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button class="round" data-month="1" aria-label="Próximo mês">${icon('arrow')}</button></div><div class="metrics"><div class="metric"><span class="muted">Pago no mês</span><strong>${money(paid)}</strong><span class="helper">Valores registrados</span></div><div class="metric"><span class="muted">A pagar</span><strong>${money(pending)}</strong><span class="helper">Compromissos do mês</span></div><div class="metric"><span class="muted">Total previsto</span><strong>${money(paid+pending)}</strong><span class="helper">Pago + a pagar</span></div></div><div class="chips">${['Todos','A pagar','Pagos'].map(f=>`<button class="chip ${financeFilter===f?'selected':''}" data-finance-filter="${f}">${f}</button>`).join('')}</div><section class="card">${bills.filter(b=>financeFilter==='Todos'||(financeFilter==='Pagos'?b.paid:!b.paid)).sort((a,b)=>a.date.localeCompare(b.date)).map(billRow).join('')||'<div class="empty">Nenhum registro nesta seleção.</div>'}</section>`}
function plans(){return heading('Planos','',button('Novo','new-plan'))+`<div class="chips">${['Todos','Casa','Filho','Carro','Família'].map(f=>`<button class="chip ${planFilter===f?'selected':''}" data-plan-filter="${f}">${f}</button>`).join('')}</div><div class="project-grid">${state.plans.filter(p=>planFilter==='Todos'||p.area===planFilter).map(p=>`<button class="card project" data-plan="${p.id}"><span class="pill">${p.area} · ${p.status}</span><h2>${esc(p.name)}</h2><p>${esc(p.detail)}</p><div class="progress"><span style="width:${planProgress(p)}%"></span></div><span class="row-meta">${p.due?'Até '+niceDate(p.due)+' · ':''}${p.checklist?.length?p.checklist.filter(i=>i.done).length+'/'+p.checklist.length+' itens · ':''}Ver plano →</span></button>`).join('')||'<p>Nenhum plano nesta área.</p>'}</div><div class="section-label"><h2>Tarefas da família</h2><button class="text-button" data-action="new-task">Adicionar tarefa</button></div><section class="card">${state.tasks.filter(t=>planFilter==='Todos'||t.area===planFilter).map(taskRow).join('')||'<p>Nenhuma tarefa nesta área.</p>'}</section>`}
function render(){const tabs={hoje:'Hoje',agenda:'Agenda',mercado:'Mercado',financas:'Finanças',planos:'Planos'};$('#navigation').innerHTML='<div class="nav-brand">casa</div>'+Object.entries(tabs).map(([id,name])=>`<a href="#${id}" class="nav-link ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span></a>`).join('');$('#main').innerHTML=({hoje:home,agenda,mercado:market,financas:finances,planos:plans}[tab])();bind()}
function navigate(t){if(location.hash==='#'+t){tab=t;render()}else location.hash=t}
function editItem(id){const i=state.items.find(i=>i.id===id);openModal('Detalhes do item',`<form id="item-form" class="form-fields"><label>Nome<input name="name" value="${esc(i.name)}" required maxlength="100"></label><label>Quantidade ou observação<input name="qty" value="${esc(i.qty)}" placeholder="Ex.: 60 unidades"></label><label>Categoria<select name="sector">${state.marketCategories.map(s=>`<option value="${esc(s)}" ${s===i.sector?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="inline"><input type="checkbox" name="track" ${i.track?'checked':''}>Acompanhar reposição</label><p class="helper">A compra e a nova necessidade ajudam a estimar a duração. Não cria uma despesa.</p><div class="form-actions"><button type="button" id="delete-item">Excluir</button><button class="primary">Salvar</button></div></form>`);$('#delete-item').onclick=()=>{$('#dialog').close();commit(()=>state.items=state.items.filter(x=>x.id!==id),'Item removido.')};$('#item-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('name').trim())return;Object.assign(i,{name:f.get('name').trim(),qty:f.get('qty').trim(),sector:f.get('sector'),track:f.has('track')});save();$('#dialog').close();render();toast('Item atualizado.')}}
function toggleItem(id){commit(()=>{const i=state.items.find(x=>x.id===id);i.done=!i.done;if(i.track&&i.done){let p=state.products.find(p=>p.name.toLowerCase()===i.name.toLowerCase());if(!p){p={id:uid(),name:i.name,history:[],cycles:0};state.products.push(p)}p.history.push({item:id,previous:p.bought,date:base});p.bought=base}else if(i.track&&!i.done){const p=state.products.find(p=>p.history.some(h=>h.item===id));if(p){let index=p.history.findLastIndex(h=>h.item===id);p.bought=p.history[index].previous;p.history.splice(index,1)}}},'Lista atualizada.');}
function billForm(){openModal('Registrar despesa',`<form id="bill-form" class="form-fields"><label>Estado<select name="status"><option value="pending">Tenho a pagar</option><option value="paid">Já paguei</option></select></label><label>Descrição<input name="name" required maxlength="100" placeholder="Ex.: Conserto da máquina"></label><div class="split"><label>Valor total (R$)<input name="amount" inputmode="decimal" required placeholder="0,00" pattern="[0-9]+([,.][0-9]{1,2})?"></label><label>Data ou 1º vencimento<input name="date" type="date" value="${base}" required></label></div><div class="split"><label>Categoria<select name="category">${categoryOptions()}</select></label><label>Parcelas<input name="count" type="number" min="1" max="60" value="1" required></label></div><details class="category-add"><summary>Adicionar categoria</summary><label>Nome da nova categoria<input name="newCategory" maxlength="40" placeholder="Ex.: Saúde"></label><button type="button" id="add-category">Criar categoria</button><p id="category-status" class="helper" role="status"></p></details><label>Quem pagou<select name="payer">${owners(reminderViewer)}</select></label><p class="helper">Disponível para qualquer forma de pagamento. Em “Já paguei”, somente a primeira parcela fica paga.</p><div id="installment-preview" class="preview-table" aria-live="polite"></div><div class="form-actions"><button class="primary">Salvar registro</button></div></form>`);const form=$('#bill-form');$('#add-category').onclick=()=>{const input=form.elements.newCategory;const name=input.value.trim();if(!name){$('#category-status').textContent='Informe o nome da categoria.';input.focus();return}const category=addCategory(name);form.elements.category.innerHTML=categoryOptions(category);input.value='';$('#category-status').textContent='Categoria disponível e selecionada.';};function values(){const f=new FormData(form);let amount=Math.round(Number(String(f.get('amount')).replace(',','.'))*100),count=Number(f.get('count'));return{f,amount,count}}function preview(){const {f,amount,count}=values();$('#installment-preview').innerHTML=amount>0&&count>0&&count<=60&&f.get('date')?installments(amount,count,f.get('date')).map((p,n)=>`<div><span>${n+1}/${count} · ${niceDate(p.date)}</span><strong>${money(p.amount)}</strong></div>`).join(''):''}form.oninput=preview;form.onsubmit=e=>{e.preventDefault();const {f,amount,count}=values();if(!f.get('name').trim()||!Number.isFinite(amount)||amount<=0||!Number.isInteger(count)||count<1||count>60)return;const parts=installments(amount,count,f.get('date'));commit(()=>{parts.forEach((p,n)=>state.bills.push({id:uid(),name:f.get('name').trim()+(count>1?` · ${n+1}/${count}`:''),...p,paid:f.get('status')==='paid'&&n===0,payer:f.get('payer'),category:f.get('category')}))},'Registro salvo.');$('#dialog').close()}}
function installments(total,count,start){const [year,month,day]=start.split('-').map(Number);return Array.from({length:count},(_,n)=>{const last=new Date(year,month+n,0).getDate();return{date:iso(new Date(year,month-1+n,Math.min(day,last))),amount:Math.floor(total/count)+(n===count-1?total%count:0)}})}
function newPlan(task=false){openModal(task?'Nova tarefa':'Novo plano',`<form id="plan-form" class="form-fields"><label>Título<input name="name" required maxlength="100" autofocus></label><label>Área<select name="area"><option>Casa</option><option>Filho</option><option>Carro</option><option>Família</option></select></label>${task?'<label>Responsável<select name="owner"><option>Sem responsável</option>${owners(reminderViewer)}</select></label>':'<label>Próxima ação<input name="detail" placeholder="Pode ficar para depois"></label>'}<label>Prazo (opcional)<input type="date" name="due"></label><div class="form-actions"><button class="primary">Criar ${task?'tarefa':'plano'}</button></div></form>`);$('#plan-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('name').trim())return;commit(()=>task?state.tasks.push({id:uid(),name:f.get('name').trim(),area:f.get('area'),owner:f.get('owner'),due:f.get('due'),done:false}):state.plans.push({id:uid(),name:f.get('name').trim(),area:f.get('area'),detail:f.get('detail'),due:f.get('due'),checklist:[],status:'Ideias',progress:0}),'Registro criado.');$('#dialog').close()}}
function about(){settingsModal()}
const actions={'market-categories':marketCategories,agenda:()=>navigate('agenda'),mercado:()=>navigate('mercado'),financas:()=>navigate('financas'),planos:()=>navigate('planos'),clear:()=>commit(()=>state.items=state.items.filter(i=>!i.done),'Itens comprados removidos.'),'new-bill':billForm,'new-plan':()=>newPlan(),'new-task':()=>newPlan(true)};
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());document.querySelectorAll('[data-item]').forEach(b=>b.onchange=()=>toggleItem(b.dataset.item));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editItem(b.dataset.edit));document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>commit(()=>{const t=state.tasks.find(t=>t.id===b.dataset.task);t.done=!t.done},'Tarefa atualizada.'));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.day;render()});document.querySelectorAll('[data-finance-filter]').forEach(b=>b.onclick=()=>{financeFilter=b.dataset.financeFilter;render()});document.querySelectorAll('[data-plan-filter]').forEach(b=>b.onclick=()=>{planFilter=b.dataset.planFilter;render()});document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{let d=new Date(financeMonth+'-15T12:00:00');d.setMonth(d.getMonth()+Number(b.dataset.month));financeMonth=iso(d).slice(0,7);render()});document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{const bill=state.bills.find(x=>x.id===b.dataset.pay);openModal('Registrar pagamento',`<p>${esc(bill.name)} · <strong>${money(bill.amount)}</strong></p><form id="pay-form" class="form-fields"><label>Data do pagamento<input type="date" name="date" value="${base}" required></label><label>Quem pagou<select name="payer">${owners(reminderViewer)}</select></label><div class="form-actions"><button class="primary">Marcar como pago</button></div></form>`);$('#pay-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);commit(()=>{bill.paid=true;bill.date=f.get('date');bill.payer=f.get('payer')},'Pagamento registrado.');$('#dialog').close()}});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{const e=events[Number(b.dataset.event)];openModal(esc(e.title),`<p>${niceDate(e.day)} · ${e.time}</p><p>${esc(e.local)}</p><a class="button-link" href="https://calendar.google.com/calendar/u/0/r" target="_blank" rel="noopener">Abrir Google Calendar</a>`)});document.querySelectorAll('[data-refill]').forEach(b=>b.onclick=()=>{const p=state.products.find(p=>p.id===b.dataset.refill);if(state.items.some(i=>!i.done&&i.name.toLowerCase()===p.name.toLowerCase()))return toast('Este produto já está na lista.');commit(()=>{state.items.push({id:uid(),name:p.name,qty:'',sector:'Cuidados',track:true,done:false});p.needed=base},'Produto adicionado ao mercado.')});document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>editPlan(b.dataset.plan));if($('#add-item'))$('#add-item').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;state.items.push({id:uid(),name,qty:'',sector:filter==='Todos'?'Outros':filter,done:false});filter='Todos';save();render();$('#add-item input').focus();toast('Item adicionado.')};}
function marketCategories(){
 openModal('Categorias do mercado', '<p class="helper">Ao remover uma categoria, os itens passam para Outros.</p><div id="market-category-list" class="category-list"></div><form id="category-form" class="form-fields"><label>Nova categoria<input name="name" maxlength="40" required placeholder="Ex.: Limpeza"></label><button class="primary">Adicionar categoria</button><p id="market-category-status" class="helper" role="status"></p></form>');
 function draw(){
  $('#market-category-list').innerHTML=state.marketCategories.map((c,n)=>`<div class="row"><div class="row-content"><strong>${esc(c)}</strong><span class="row-meta">${state.items.filter(i=>i.sector===c).length} itens</span></div>${c==='Outros'?'<span class="pill">Padrão</span>':`<button class="text-button" data-remove-category="${n}" aria-label="Remover categoria ${esc(c)}">Remover</button>`}</div>`).join('');
  document.querySelectorAll('[data-remove-category]').forEach(btn=>btn.onclick=()=>{const c=state.marketCategories[Number(btn.dataset.removeCategory)];const previous=structuredClone(state);state.marketCategories=state.marketCategories.filter(x=>x!==c);state.items.forEach(i=>{if(i.sector===c)i.sector='Outros'});if(filter===c)filter='Todos';save();render();draw();$('#market-category-status').innerHTML='Categoria removida. <button type="button" id="undo-category">Desfazer</button>';$('#undo-category').onclick=()=>{state=previous;save();render();draw();$('#market-category-status').textContent='Categoria restaurada.'}});
 }
 draw();
 $('#category-form').onsubmit=e=>{e.preventDefault();const input=e.target.elements.name;const name=input.value.trim();if(!name)return;if(name.toLocaleLowerCase('pt-BR')==='todos'||state.marketCategories.some(c=>c.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'))){$('#market-category-status').textContent='Este nome já está em uso.';return}state.marketCategories.push(name);save();render();draw();input.value='';input.focus();$('#market-category-status').textContent='Categoria adicionada.'};
}
function todayEvents(){
 const list=events.filter(e=>e.day===base);
 return `<section class="card today-card"><div class="card-head"><h2><span class="section-icon">${icon('agenda')}</span>Eventos de hoje</h2><button class="text-button" data-action="agenda">Ver agenda</button></div><div class="today-events" tabindex="0" role="region" aria-label="Eventos de hoje. Role para ver todos os compromissos.">${list.map(e=>`<button class="today-event" data-event="${events.indexOf(e)}"><span class="event-time">${e.allDay?'Dia inteiro':e.time}</span><span class="event-copy"><strong>${esc(e.title)}</strong><span>${esc(e.local)}</span></span>${icon('arrow')}</button>`).join('')||'<div class="empty">Nenhum evento para hoje.</div>'}</div>${list.length>3?`<p class="scroll-hint">${list.length} eventos · role para ver todos ↓</p>`:''}</section>`;
}
function categoryOptions(selected){return state.categories.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('')}
function addCategory(name){state.categories??=['Casa','Mercado','Filho','Carro','Família'];const existing=state.categories.find(c=>c.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'));if(existing)return existing;state.categories.push(name);save();return name}
function planProgress(p){const list=p.checklist||[];return list.length?Math.round(list.filter(i=>i.done).length/list.length*100):p.status==='Concluídos'?100:0}
function owners(selected='Sem responsável'){return ['Sem responsável','Diego','Minha esposa'].map(o=>`<option ${o===selected?'selected':''}>${o}</option>`).join('')}
function editPlan(id){
 const current=state.plans.find(p=>p.id===id);
 const draft=structuredClone(current);draft.checklist??=[];
 openModal(esc(draft.name),`<form id="edit-plan" class="form-fields"><label>Próxima ação<input name="detail" value="${esc(draft.detail)}"></label><div class="split"><label>Prazo do plano<input type="date" name="due" value="${esc(draft.due||'')}"></label><label>Estado<select name="status">${['Ideias','Em andamento','Concluídos'].map(v=>`<option ${v===draft.status?'selected':''}>${v}</option>`).join('')}</select></label></div><section class="checklist-section" aria-labelledby="checklist-title"><div class="card-head"><h3 id="checklist-title">Checklist do plano</h3><span id="checklist-count" class="pill"></span></div><div id="checklist-items"></div><div class="checklist-compose"><label>Novo item<input id="checklist-name" maxlength="120" placeholder="Ex.: Pedir dois orçamentos"></label><div class="split"><label>Responsável pelo novo item<select id="checklist-owner">${owners()}</select></label><label>Prazo do novo item<input id="checklist-due" type="date"></label></div><button type="button" id="checklist-add">${icon('plus')} Adicionar à checklist</button><p class="helper" id="checklist-status" role="status"></p></div></section><div class="form-actions"><button class="primary">Salvar plano</button></div></form>`);
 function draw(){
  $('#checklist-count').textContent=`${draft.checklist.filter(i=>i.done).length}/${draft.checklist.length}`;
  $('#checklist-items').innerHTML=draft.checklist.map(i=>`<div class="checklist-item"><div class="checklist-top"><label class="check-label"><input type="checkbox" class="check" data-check="${i.id}" ${i.done?'checked':''} aria-label="Concluir ${esc(i.name)}"></label><label class="checklist-name"><span class="helper">Item</span><input data-name="${i.id}" value="${esc(i.name)}" required maxlength="120" aria-label="Nome do item ${esc(i.name)}"></label><button type="button" class="round" data-remove="${i.id}" aria-label="Excluir ${esc(i.name)}">${icon('close')}</button></div><div class="split"><label>Responsável<select data-owner="${i.id}" aria-label="Responsável por ${esc(i.name)}">${owners(i.owner)}</select></label><label>Prazo<input type="date" data-due="${i.id}" value="${esc(i.due||'')}" aria-label="Prazo de ${esc(i.name)}"></label></div></div>`).join('')||'<p class="helper">Divida o plano em passos e escolha quem cuida de cada um.</p>';
  $('#checklist-items').querySelectorAll('[data-check]').forEach(input=>input.onchange=()=>{draft.checklist.find(i=>i.id===input.dataset.check).done=input.checked;$('#checklist-count').textContent=`${draft.checklist.filter(i=>i.done).length}/${draft.checklist.length}`});
  for(const field of ['name','owner','due'])$('#checklist-items').querySelectorAll(`[data-${field}]`).forEach(input=>input.oninput=()=>{draft.checklist.find(i=>i.id===input.dataset[field])[field]=input.value});
  $('#checklist-items').querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>{draft.checklist=draft.checklist.filter(i=>i.id!==btn.dataset.remove);draw()});
 }
 draw();
 function add(){const name=$('#checklist-name').value.trim();if(!name){$('#checklist-status').textContent='Informe o nome do item.';$('#checklist-name').focus();return}draft.checklist.push({id:uid(),name,owner:$('#checklist-owner').value,due:$('#checklist-due').value,done:false});draw();$('#checklist-name').value='';$('#checklist-status').textContent='Item adicionado. Salve o plano para guardar as alterações.';$('#checklist-name').focus()}
 $('#checklist-add').onclick=add;
 $('#checklist-name').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();add()}};
 $('#edit-plan').onsubmit=e=>{e.preventDefault();if(draft.checklist.some(i=>!i.name.trim()))return;const f=new FormData(e.target);draft.detail=f.get('detail');draft.due=f.get('due');draft.status=f.get('status');draft.progress=planProgress(draft);commit(()=>{state.plans[state.plans.findIndex(p=>p.id===id)]=draft},'Plano e checklist salvos.');$('#dialog').close()};
}

$('#profile').onclick=about;window.addEventListener('hashchange',()=>{tab=['hoje','agenda','mercado','financas','planos'].includes(location.hash.slice(1))?location.hash.slice(1):'hoje';render();window.scrollTo(0,0)});tab=['hoje','agenda','mercado','financas','planos'].includes(location.hash.slice(1))?location.hash.slice(1):'hoje';render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_family_prototype',description:'Abre uma seção do protótipo local. Não conecta serviços nem altera registros.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['hoje','agenda','mercado','financas','planos']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({section})=>{if(!['hoje','agenda','mercado','financas','planos'].includes(section))throw Error('Seção inválida');tab=section;history.replaceState(null,'','#'+section);render();return{section,prototype:true}}})}catch{}}
// Local prototype: no background push, account access, or Google Calendar writes.
state.messages ??= [];
state.localEvents ??= [];
state.contacts ??= [];
let reminderViewer = 'Diego';
let familyNames=['Diego','Minha esposa'];
function whatsappUrl(message) {
 return `https://wa.me/${message.phone}?text=${encodeURIComponent(message.text)}`;
}
function normalizePhone(value) {
 let number = value.replace(/[^0-9]/g, '');
 if (!value.trim().startsWith('+') && (number.length === 10 || number.length === 11)) number = '55' + number;
 return /^[1-9]\d{7,14}$/.test(number) ? number : null;
}
function scheduledEvents() {
 for (let n = events.length - 1; n >= 0; n--) if (events[n].messageId || events[n].localEventId || events[n].googleId) events.splice(n, 1);
 for (const event of state.localEvents || []) events.push({...event,day:event.date,localEventId:event.id});
 for (const event of googleEvents) events.push(event);
 for (const m of state.messages || []) events.push({day:m.date,time:m.time,title:`Mensagem para ${m.contact || '+' + m.phone}`,local:`${m.assignee} · ${m.sent ? 'Envio confirmado' : 'A enviar'}`,area:'Mensagem',messageId:m.id});
 events.sort((a,b)=>(a.day+(a.allDay?'':a.time||'')).localeCompare(b.day+(b.allDay?'':b.time||'')));
}
function messageForm(id) {
 const previous = state.messages.find(m=>m.id===id);
 const next = new Date(Date.now()+3600000);
 const m = previous || {contact:'',phone:'',text:'',date:iso(next),time:`${String(next.getHours()).padStart(2,'0')}:${String(next.getMinutes()).padStart(2,'0')}`,assignee:'Diego'};
 openModal(previous?'Editar agendamento':'Agendar mensagem',`<form id="message-form" class="form-fields">
 ${state.contacts.length?`<label>Contato salvo<select id="saved-contact"><option value="">Novo contato ou número</option>${state.contacts.map((c,n)=>`<option value="${n}">${esc(c.name || '+'+c.phone)} · +${esc(c.phone)}</option>`).join('')}</select></label>`:''}
 <button type="button" id="phone-contact">Escolher dos contatos do celular</button><p id="contact-picker-status" class="helper" role="status"></p><label id="contact-number-choice" hidden>Telefone do contato<select id="contact-number-select"></select></label><label>Nome do contato (opcional)<input name="contact" maxlength="80" value="${esc(m.contact)}" autocomplete="off" placeholder="Ex.: Encanador"></label>
 <label>Telefone com DDD<input name="phone" type="tel" required maxlength="24" value="${m.phone?'+'+esc(m.phone):''}" placeholder="27 99999-9999" autocomplete="off"></label>
 <p class="helper">Números brasileiros aceitam DDD. Para outro país, use + e o código do país.</p>
 <label>Mensagem<textarea name="text" required maxlength="4000" rows="4" placeholder="Escreva a mensagem para enviar depois.">${esc(m.text)}</textarea></label>
 <div class="split"><label>Data<input type="date" name="date" value="${esc(m.date)}" required></label><label>Horário<input type="time" name="time" value="${esc(m.time)}" required></label></div>
 <label>Responsável<select name="assignee">${familyNames.map(p=>`<option ${m.assignee===p?'selected':''}>${p}</option>`).join('')}</select></label>
 <p class="helper">O Casa não envia notificações neste momento. Abra a Agenda para ver o agendamento.</p>
 <p id="message-error" class="form-error" role="alert"></p><div class="form-actions"><button class="primary">Salvar agendamento</button></div></form>`);
 const form=$('#message-form');
 setupContactPicker(form);
 if($('#saved-contact')) $('#saved-contact').onchange=e=>{if(e.target.value==='')return;const c=state.contacts[Number(e.target.value)];form.elements.contact.value=c.name;form.elements.phone.value='+'+c.phone};
 form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),phone=normalizePhone(f.get('phone')),text=f.get('text').trim(),when=new Date(`${f.get('date')}T${f.get('time')}`);
 if(!phone){$('#message-error').textContent='Informe um telefone válido com DDD ou código internacional.';return}
 if(!text){$('#message-error').textContent='Escreva a mensagem.';return}
 if(!Number.isFinite(when.getTime())||when.getTime()<=Date.now()){$('#message-error').textContent='Escolha uma data e um horário futuros.';return}
 const record={id:previous?.id||uid(),contact:f.get('contact').trim(),phone,text,date:f.get('date'),time:f.get('time'),assignee:f.get('assignee'),sent:false};
 commit(()=>{state.messages??=[];state.contacts??=[];if(previous)state.messages[state.messages.findIndex(x=>x.id===id)]=record;else state.messages.push(record);if(record.contact){const c=state.contacts.find(c=>c.phone===phone);if(c)c.name=record.contact;else state.contacts.push({name:record.contact,phone})}selectedDay=record.date;},'Mensagem agendada na agenda do painel.');$('#dialog').close();
 };
}
function messageDetail(id) {
 const m=(state.messages||[]).find(x=>x.id===id);if(!m)return;
 openModal('Mensagem agendada',`<p><strong>${esc(m.contact||'Contato')}</strong> · +${esc(m.phone)}</p><p>${niceDate(m.date)} às ${esc(m.time)} · ${esc(m.assignee)}</p><div class="message-preview">${esc(m.text)}</div><p class="helper">O WhatsApp abrirá com o texto preenchido. Você ainda precisa tocar em Enviar.</p><a class="button-link whatsapp-open" href="${esc(whatsappUrl(m))}" target="_blank" rel="noopener noreferrer">Abrir conversa no WhatsApp</a><p class="helper">${m.sent?'Você marcou esta mensagem como enviada.':'Abrir a conversa não confirma o envio.'}</p><div class="message-actions"><button id="message-sent">${m.sent?'Marcar como pendente':'Já enviei'}</button><button id="message-edit">Editar</button><button id="message-delete">Cancelar agendamento</button></div>`);
 $('#message-sent').onclick=()=>{commit(()=>{m.sent=!m.sent},'Estado da mensagem atualizado.');$('#dialog').close()};
 $('#message-edit').onclick=()=>{$('#dialog').close();messageForm(id)};
 $('#message-delete').onclick=()=>{commit(()=>state.messages=state.messages.filter(x=>x.id!==id),'Agendamento cancelado.');$('#dialog').close()};
}
const originalAgenda=agenda;
agenda=function(){return originalAgenda().replace(heading('Agenda',''),heading('Agenda','',`<div class="agenda-actions">${button('Agendar evento','schedule-event')}<button class="secondary" data-action="schedule-message">${icon('plus')}Agendar mensagem</button></div>`))};
const originalBind=bind;
bind=function(){originalBind();document.querySelectorAll('[data-event]').forEach(b=>{const e=events[Number(b.dataset.event)];if(e?.messageId)b.onclick=()=>messageDetail(e.messageId);else if(e?.localEventId)b.onclick=()=>localEventDetail(e.localEventId);else if(e?.googleId)b.onclick=()=>openModal(esc(e.title),'<p>'+niceDate(e.day)+' · '+esc(e.allDay?'Dia inteiro':e.time)+'</p><p>'+esc(e.local||'Google Calendar')+'</p><p class="helper">Evento do Google. Abra o Google Calendar para editar.</p><a class="button-link" href="https://calendar.google.com/calendar/u/0/r" target="_blank" rel="noopener">Abrir Google Calendar</a>')})};
const originalRender=render;
render=function(){scheduledEvents();originalRender()};
actions['schedule-message']=()=>messageForm();
render();


function agendaDay(list){
 const messages=list.filter(e=>e.messageId),regular=list.filter(e=>!e.messageId);
 const stack=messages.length?`<div class="daily-messages"><div class="daily-message-label">Mensagens · ${messages.length}</div>${messages.map(e=>{const m=state.messages.find(m=>m.id===e.messageId);return `<button class="compact-message ${m.sent?'message-sent':''}" data-event="${events.indexOf(e)}"><span class="compact-message-top"><strong>${esc(m.contact||'+'+m.phone)}</strong><time>${esc(m.time)}</time></span><span class="message-snippet">${esc(m.text)}</span><span class="message-assignee">${esc(m.assignee)}${m.sent?' · Enviada':''}</span></button>`}).join('')}</div>`:'';
 return stack+regular.map(e=>`<div class="agenda-row"><span class="time">${e.allDay?'Dia inteiro':esc(e.time)}</span><div class="agenda-body"><button data-event="${events.indexOf(e)}"><h2>${esc(e.title)}</h2></button>${e.local?`<p class="event-location">${icon('pin')}${esc(e.local)}</p>`:''}${e.area?`<span class="pill">${esc(e.area)}</span>`:''}</div></div>`).join('')+(!list.length?'<p>Nenhum compromisso neste dia.</p>':'');
}
function setupContactPicker(form){
 const button=$('#phone-contact'),status=$('#contact-picker-status');
 const supported=window.isSecureContext&&!!navigator.contacts?.select;
 if(!supported){button.disabled=true;status.textContent='Este navegador não oferece acesso aos contatos. Digite o telefone ou escolha um contato salvo no app.';return}
 status.textContent='Você escolhe quais dados compartilhar. O painel não importa sua lista inteira.';
 button.onclick=async()=>{try{
  const selected=await navigator.contacts.select(['name','tel'],{multiple:false});
  if(!selected.length)return;
  const contact=selected[0],numbers=(contact.tel||[]).filter(Boolean);
  if(!numbers.length){status.textContent='Este contato não tem telefone. Escolha outro contato.';return}
  form.elements.contact.value=contact.name?.[0]||'';
  form.elements.phone.value=numbers[0];
  const label=$('#contact-number-choice'),select=$('#contact-number-select');label.hidden=numbers.length<2;
  select.innerHTML=numbers.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');
  select.onchange=()=>form.elements.phone.value=select.value;
  status.textContent=numbers.length>1?'Escolha qual telefone usar.':'Contato preenchido. Confira o número antes de salvar.';
 }catch(error){status.textContent=error.name==='AbortError'?'Seleção cancelada.':'Não foi possível acessar os contatos. Você pode informar o telefone.'}};
}
function eventForm(id){
 const previous=(state.localEvents||[]).find(e=>e.id===id),next=new Date(Date.now()+3600000);
 const event=previous||{title:'',date:iso(next),time:`${String(next.getHours()).padStart(2,'0')}:00`,end:'',local:'',allDay:false,description:''};
 openModal(previous?'Editar evento':'Agendar evento',`<form id="event-form" class="form-fields"><label>Título<input name="title" required maxlength="120" value="${esc(event.title)}" placeholder="Ex.: Consulta do pequeno"></label><label>Data<input type="date" name="date" required value="${esc(event.date)}"></label><label class="inline"><input type="checkbox" name="allDay" ${event.allDay?'checked':''}>Dia inteiro</label><div class="split" id="event-times"><label>Início<input type="time" name="time" value="${esc(event.time||'')}"></label><label>Fim (opcional)<input type="time" name="end" value="${esc(event.end||'')}"></label></div><label>Local (opcional)<input name="local" maxlength="200" value="${esc(event.local)}"></label><label>Observações (opcional)<textarea name="description" rows="3" maxlength="2000">${esc(event.description||'')}</textarea></label><p id="event-error" class="form-error" role="alert"></p><div class="form-actions"><button class="primary">Salvar evento</button></div></form>`);
 const form=$('#event-form'),allDay=form.elements.allDay,times=$('#event-times');function updateTimes(){times.hidden=allDay.checked;form.elements.time.required=!allDay.checked}allDay.onchange=updateTimes;updateTimes();
 form.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),isAllDay=f.has('allDay');if(!title){$('#event-error').textContent='Informe o título.';return}if(!isAllDay&&!f.get('time')){$('#event-error').textContent='Informe o horário de início.';return}if(!isAllDay&&f.get('end')&&f.get('end')<=f.get('time')){$('#event-error').textContent='O fim deve ser posterior ao início, no mesmo dia.';return}const record={id:previous?.id||uid(),title,date:f.get('date'),allDay:isAllDay,time:isAllDay?'':f.get('time'),end:isAllDay?'':f.get('end'),local:f.get('local').trim(),description:f.get('description').trim()};commit(()=>{state.localEvents??=[];if(previous)state.localEvents[state.localEvents.findIndex(e=>e.id===id)]=record;else state.localEvents.push(record);selectedDay=record.date},'Evento salvo na agenda do painel.');$('#dialog').close()};
}
