function categoryManager(kind){const field=kind==='market'?'marketCategories':'categories',fallback=kind==='market'?'Outros':'Sem categoria';state[field]??=[];
 openModal(kind==='market'?'Categorias do mercado':'Categorias das despesas',`<p class="helper">Excluir uma categoria move os registros para ${fallback}.</p><div id="category-crud-list"></div><form id="category-crud-form" class="form-fields"><label>Nova categoria<input name="name" required maxlength="40"></label><button class="primary">Adicionar categoria</button><p id="category-crud-status" role="status" class="helper"></p></form>`);
 function draw(){const root=$('#category-crud-list');root.innerHTML=state[field].map((c,n)=>`<div class="category-crud-row"><input aria-label="Nome da categoria ${esc(c)}" value="${esc(c)}" data-cat-input="${n}" maxlength="40" ${c===fallback?'disabled':''}><button type="button" data-cat-save="${n}" aria-label="Salvar categoria ${esc(c)}" ${c===fallback?'disabled':''}>Salvar</button><button type="button" data-cat-delete="${n}" aria-label="Excluir categoria ${esc(c)}" ${c===fallback?'disabled':''}>${icon('close')}</button></div>`).join('');
 root.querySelectorAll('[data-cat-save]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.catSave),old=state[field][index],name=root.querySelector(`[data-cat-input="${index}"]`).value.trim();if(!valid(name,old))return;state[field][index]=name;records(old,name);persist('Categoria renomeada.');draw()});
 root.querySelectorAll('[data-cat-delete]').forEach(b=>b.onclick=()=>{const old=state[field][Number(b.dataset.catDelete)],before=structuredClone(state);state[field]=state[field].filter(c=>c!==old);if(!state[field].includes(fallback))state[field].push(fallback);records(old,fallback);persist('Categoria removida.');draw();$('#category-crud-status').innerHTML='Categoria removida. <button type="button" id="restore-category">Desfazer</button>';$('#restore-category').onclick=()=>{if(window.Casa?.isOnline()){toast('Para restaurar, cadastre a categoria novamente.');return}state=before;persist('Categoria restaurada.');draw()}});
 }
 function records(old,name){if(kind==='market'){state.items.forEach(i=>{if(i.sector===old)i.sector=name});if(filter===old)filter=name}else state.bills.forEach(b=>{if(b.category===old)b.category=name})}
 function valid(name,old){if(!name||name.toLocaleLowerCase('pt-BR')==='todos'||state[field].some(c=>c!==old&&c.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'))){$('#category-crud-status').textContent='Use um nome não vazio e diferente das outras categorias.';return false}return true}
 function persist(message){save();render();$('#category-crud-status').textContent=message}
 draw();$('#category-crud-form').onsubmit=e=>{e.preventDefault();const name=e.target.elements.name.value.trim();if(!valid(name))return;state[field].push(name);persist('Categoria adicionada.');draw();e.target.reset()};
}
