// Keep native date fields so Android can open its calendar picker.
function addDatePickers(){
 document.querySelectorAll('input[type="date"]:not([data-picker-ready])').forEach(input=>{
  input.dataset.pickerReady='true';
  const wrap=document.createElement('span');wrap.className='date-field';input.before(wrap);wrap.append(input);
  const button=document.createElement('button');button.type='button';button.className='date-picker-button';button.setAttribute('aria-label','Abrir calendário');button.textContent='📅';
  button.onclick=()=>{try{if(input.showPicker)input.showPicker();else input.focus()}catch{input.focus()}};
  wrap.append(button);
 });
}
const dateObserver=new MutationObserver(addDatePickers);dateObserver.observe(document.body,{childList:true,subtree:true});addDatePickers();
