function recurringBillForm(){
 openModal('Registrar despesa',`<form id="bill-form" class="form-fields"><label>Estado<select name="status"><option value="pending">Tenho a pagar</option><option value="paid">Já paguei</option></select></label><label>Descrição<input name="name" required maxlength="100" placeholder="Ex.: Aluguel"></label><div class="split"><label>Valor total (R$)<input name="amount" inputmode="decimal" required placeholder="0,00"></label><label>Data ou 1º vencimento<input name="date" type="date" value="${base}" required></label></div><div class="split"><label>Categoria<select name="category">${categoryOptions()}</select></label><label>Parcelas<input name="count" type="number" min="1" max="60" value="1" required></label></div><label class="inline"><input type="checkbox" name="recurring">Despesa recorrente</label><label>Repetir<select name="frequency"><option value="monthly">Todo mês</option><option value="weekly">Toda semana</option><option value="yearly">Todo ano</option></select></label><label>Quem pagou<select name="payer">${owners(reminderViewer)}</select></label><p class="helper">Uma recorrência cria o compromisso atual e guarda a regra para gerar os próximos vencimentos.</p><div id="installment-preview" class="preview-table" aria-live="polite"></div><div class="form-actions"><button class="primary">Salvar registro</button></div></form>`);
 const form=$('#bill-form');function values(){const f=new FormData(form),amount=Math.round(Number(String(f.get('amount')).replace(',','.'))*100),count=Number(f.get('count'));return{f,amount,count}}function preview(){const {f,amount,count}=values();$('#installment-preview').innerHTML=amount>0&&count>0&&count<=60&&f.get('date')?installments(amount,count,f.get('date')).map((p,n)=>`<div><span>${n+1}/${count} · ${niceDate(p.date)}</span><strong>${money(p.amount)}</strong></div>`).join(''):''}form.oninput=preview;form.onsubmit=e=>{e.preventDefault();const {f,amount,count}=values();if(!f.get('name').trim()||!Number.isFinite(amount)||amount<=0||!Number.isInteger(count)||count<1||count>60)return;const recurrence=f.has('recurring')?{frequency:f.get('frequency'),start:f.get('date')}:null;const parts=installments(amount,count,f.get('date'));commit(()=>{state.recurringBills??=[];if(recurrence)state.recurringBills.push({id:uid(),name:f.get('name').trim(),amount,category:f.get('category'),payer:f.get('payer'),...recurrence});parts.forEach((p,n)=>state.bills.push({id:uid(),name:f.get('name').trim()+(count>1?` · ${n+1}/${count}`:''),...p,paid:f.get('status')==='paid'&&n===0,payer:f.get('payer'),category:f.get('category'),recurring:Boolean(recurrence),recurrence}))},'Registro salvo.');$('#dialog').close()};
}
