const editExpenseBeforeRecurring=editExpense;
editExpense=function(id){
 const b=state.bills.find(x=>x.id===id);if(!b)return;
 openModal('Editar despesa',`<form id="expense-edit" class="form-fields"><label>Descrição<input name="name" required value="${esc(b.name)}" maxlength="120"></label><label>Valor (R$)<input name="amount" required inputmode="decimal" value="${(b.amount/100).toFixed(2).replace('.',',')}"></label><label>Data<input name="date" type="date" value="${b.date}" required></label><label>Categoria<select name="category">${categoryOptions(b.category)}</select></label><label class="inline"><input type="checkbox" name="paid" ${b.paid?'checked':''}>Pago</label><label class="inline"><input type="checkbox" name="recurring" ${b.recurring?'checked':''}>Despesa recorrente</label><label>Repetir<select name="frequency"><option value="monthly" ${b.recurrence?.frequency==='monthly'?'selected':''}>Todo mês</option><option value="weekly" ${b.recurrence?.frequency==='weekly'?'selected':''}>Toda semana</option><option value="yearly" ${b.recurrence?.frequency==='yearly'?'selected':''}>Todo ano</option></select></label><p class="helper">A edição afeta somente este registro.</p><div class="form-actions"><button type="button" id="expense-delete">Excluir despesa</button><button class="primary">Salvar despesa</button></div></form>`);
 $('#expense-edit').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),amount=Math.round(Number(String(f.get('amount')).replace(',','.'))*100);if(!f.get('name').trim()||!Number.isFinite(amount)||amount<=0)return;commit(()=>{b.name=f.get('name').trim();b.amount=amount;b.date=f.get('date');b.category=f.get('category');b.paid=f.has('paid');b.recurring=f.has('recurring');b.recurrence=b.recurring?{frequency:f.get('frequency'),start:b.date}:null},'Despesa atualizada.');$('#dialog').close()};
 $('#expense-delete').onclick=()=>{commit(()=>state.bills=state.bills.filter(x=>x.id!==id),'Despesa removida.');$('#dialog').close()};
};

// Finance records use one shape for expenses and income. This maps cleanly to one live database table.
const transactionType=b=>b.type||'expense';
function shiftMonth(key,offset){const d=new Date(`${key}-15T12:00:00`);d.setMonth(d.getMonth()+offset);return iso(d).slice(0,7)}
function recurrenceDate(start,frequency,index){const source=new Date(`${start}T12:00:00`),day=source.getDate();if(frequency==='weekly')source.setDate(day+index*7);else if(frequency==='yearly')source.setFullYear(source.getFullYear()+index);else{source.setDate(1);source.setMonth(source.getMonth()+index);const last=new Date(source.getFullYear(),source.getMonth()+1,0).getDate();source.setDate(Math.min(day,last))}return iso(source)}
function financeChart(){const months=Array.from({length:6},(_,index)=>shiftMonth(monthKey,index-2));const data=months.map(key=>{const rows=state.bills.filter(b=>b.date.startsWith(key));return{key,income:rows.filter(b=>transactionType(b)==='income').reduce((sum,b)=>sum+b.amount,0),expense:rows.filter(b=>transactionType(b)==='expense').reduce((sum,b)=>sum+b.amount,0)}});const max=Math.max(1,...data.flatMap(d=>[d.income,d.expense]));return `<section class="card finance-chart" aria-labelledby="finance-chart-title"><div class="card-head"><h2 id="finance-chart-title">Visão mensal</h2><div class="chart-legend"><span><i class="income-key"></i>Receitas</span><span><i class="expense-key"></i>Despesas</span></div></div><div class="chart-bars">${data.map(d=>`<div class="chart-month ${d.key>monthKey?'forecast':''} ${d.key===monthKey?'current':''}"><div class="bar-pair" title="${money(d.income)} em receitas e ${money(d.expense)} em despesas"><span class="bar income-bar" style="height:${Math.max(2,d.income/max*100)}%"></span><span class="bar expense-bar" style="height:${Math.max(2,d.expense/max*100)}%"></span></div><strong>${new Date(`${d.key}-15T12:00:00`).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</strong><small>${d.key>monthKey?'Projeção':d.key===monthKey?'Atual':''}</small></div>`).join('')}</div></section>`}
function transactionRow(b){const income=transactionType(b)==='income',settled=b.paid;return `<div class="row transaction-row ${income?'income-row':''}"><div class="icon-box">${icon(income?'plus':settled?'check':'financas')}</div><div class="row-content"><button class="expense-title" data-expense-edit="${b.id}">${esc(b.name)}</button><span class="row-meta">${income?(settled?'Recebida':'A receber'):(settled?'Paga':'Vence')} ${niceDate(b.date)} · ${esc(b.category)}${b.payer?' · '+esc(b.payer):''}</span>${b.recurring?`<span class="pill recurring-pill">Recorrente${b.occurrence?` · ${b.occurrence}/${b.occurrences}`:''}</span>`:''}</div><span class="money ${income?'income-money':''}">${income?'+ ':''}${money(b.amount)}</span>${!settled?`<button class="round" data-settle="${b.id}" aria-label="Marcar ${esc(b.name)} como ${income?'recebida':'paga'}">${icon('check')}</button>`:''}</div>`}
billRow=transactionRow;
finances=function(){const rows=state.bills.filter(b=>b.date.startsWith(financeMonth)),expenses=rows.filter(b=>transactionType(b)==='expense'),income=rows.filter(b=>transactionType(b)==='income'),expenseTotal=expenses.reduce((sum,b)=>sum+b.amount,0),incomeTotal=income.reduce((sum,b)=>sum+b.amount,0),pendingExpense=expenses.filter(b=>!b.paid).reduce((sum,b)=>sum+b.amount,0),pendingIncome=income.filter(b=>!b.paid).reduce((sum,b)=>sum+b.amount,0);const visible=rows.filter(b=>financeFilter==='Todos'||financeFilter==='Despesas'&&transactionType(b)==='expense'||financeFilter==='Receitas'&&transactionType(b)==='income'||financeFilter==='Pendentes'&&!b.paid);const actionsHtml=`<div class="finance-heading-actions"><button class="text-button" data-action="finance-categories">Editar categorias</button>${button('Registrar','new-bill')}</div>`;return heading('Finanças','',actionsHtml)+financeChart()+`<div class="month-control"><button class="round" data-month="-1" aria-label="Mês anterior">${icon('back')}</button><strong>${new Date(financeMonth+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button class="round" data-month="1" aria-label="Próximo mês">${icon('arrow')}</button></div><div class="metrics"><div class="metric"><span class="muted">Receitas</span><strong>${money(incomeTotal)}</strong><span class="helper">${money(pendingIncome)} a receber</span></div><div class="metric"><span class="muted">Despesas</span><strong>${money(expenseTotal)}</strong><span class="helper">${money(pendingExpense)} a pagar</span></div><div class="metric"><span class="muted">Saldo previsto</span><strong>${money(incomeTotal-expenseTotal)}</strong><span class="helper">Receitas − despesas</span></div></div><div class="chips">${['Todos','Despesas','Receitas','Pendentes'].map(value=>`<button class="chip ${financeFilter===value?'selected':''}" data-finance-filter="${value}">${value}</button>`).join('')}</div><section class="card">${visible.sort((a,b)=>a.date.localeCompare(b.date)).map(transactionRow).join('')||'<div class="empty">Nenhum lançamento nesta seleção.</div>'}</section>`};
function financeRecordForm(){
 openModal('Registrar lançamento',`<form id="bill-form" class="form-fields"><div class="split"><label>Tipo<select name="type"><option value="expense">Despesa</option><option value="income">Receita</option></select></label><label>Estado<select name="status"></select></label></div><label>Descrição<input name="name" required maxlength="100" placeholder="Ex.: Aluguel"></label><div class="split"><label>Valor (R$)<input name="amount" inputmode="decimal" required placeholder="0,00"></label><label>Data<input name="date" type="date" value="${base}" required></label></div><label>Categoria<select name="category">${categoryOptions()}</select></label><label id="installment-field">Parcelas<input name="count" type="number" min="1" max="60" value="1" required></label><label class="inline"><input type="checkbox" name="recurring">Repetir este lançamento</label><div class="split" id="recurrence-fields" hidden><label>Frequência<select name="frequency"><option value="monthly">Mensal</option><option value="weekly">Semanal</option><option value="yearly">Anual</option></select></label><label>Número de ocorrências<input name="occurrences" type="number" min="2" max="120" value="12"></label></div><label>Responsável<select name="payer">${owners(reminderViewer)}</select></label><div id="installment-preview" class="preview-table" aria-live="polite"></div><div class="form-actions"><button class="primary">Salvar lançamento</button></div></form>`);
 const form=$('#bill-form'),status=form.elements.status,recurrenceFields=$('#recurrence-fields'),installmentField=$('#installment-field');let lastType='';function update(){const income=form.elements.type.value==='income',recurring=form.elements.recurring.checked,currentStatus=status.value;if(lastType!==form.elements.type.value){status.innerHTML=income?'<option value="pending">A receber</option><option value="paid">Recebida</option>':'<option value="pending">A pagar</option><option value="paid">Paga</option>';if(currentStatus)status.value=currentStatus;lastType=form.elements.type.value}recurrenceFields.hidden=!recurring;installmentField.hidden=income||recurring;preview()}function values(){const f=new FormData(form),amount=Math.round(Number(String(f.get('amount')).replace(',','.'))*100),count=Number(f.get('count')||1),occurrences=Number(f.get('occurrences')||1);return{f,amount,count,occurrences}}function preview(){const {f,amount,count,occurrences}=values();const target=$('#installment-preview');if(!(amount>0)||!f.get('date')){target.innerHTML='';return}if(f.has('recurring'))target.innerHTML=Array.from({length:Math.min(occurrences,6)},(_,index)=>`<div><span>${index+1}/${occurrences} · ${niceDate(recurrenceDate(f.get('date'),f.get('frequency'),index))}</span><strong>${money(amount)}</strong></div>`).join('')+(occurrences>6?`<p class="helper">Mais ${occurrences-6} ocorrências.</p>`:'');else if(f.get('type')==='expense'&&count>1)target.innerHTML=installments(amount,count,f.get('date')).map((part,index)=>`<div><span>${index+1}/${count} · ${niceDate(part.date)}</span><strong>${money(part.amount)}</strong></div>`).join('');else target.innerHTML=''}form.elements.type.onchange=update;form.elements.recurring.onchange=update;for(const field of ['amount','date','count','frequency','occurrences'])form.elements[field]?.addEventListener('input',preview);update();form.onsubmit=e=>{e.preventDefault();const {f,amount,count,occurrences}=values(),name=f.get('name').trim(),type=f.get('type'),recurring=f.has('recurring');if(!name||!Number.isFinite(amount)||amount<=0||!Number.isInteger(count)||count<1||count>60||recurring&&(!Number.isInteger(occurrences)||occurrences<2||occurrences>120))return;const seriesId=recurring?uid():null,records=[];if(recurring){for(let index=0;index<occurrences;index++)records.push({id:uid(),name,amount,date:recurrenceDate(f.get('date'),f.get('frequency'),index),paid:f.get('status')==='paid'&&index===0,payer:f.get('payer'),category:f.get('category'),type,recurring:true,seriesId,occurrence:index+1,occurrences,recurrence:{frequency:f.get('frequency'),start:f.get('date'),occurrences}})}else if(type==='expense'&&count>1){installments(amount,count,f.get('date')).forEach((part,index)=>records.push({id:uid(),name:`${name} · ${index+1}/${count}`,...part,paid:f.get('status')==='paid'&&index===0,payer:f.get('payer'),category:f.get('category'),type}))}else records.push({id:uid(),name,amount,date:f.get('date'),paid:f.get('status')==='paid',payer:f.get('payer'),category:f.get('category'),type});commit(()=>{state.bills.push(...records);if(recurring){state.recurringBills??=[];state.recurringBills.push({id:seriesId,name,amount,type,category:f.get('category'),payer:f.get('payer'),frequency:f.get('frequency'),start:f.get('date'),occurrences})}},records.length===1?'Lançamento salvo.':`${records.length} lançamentos criados.`);$('#dialog').close()};
}
