editExpense=function(id){const b=state.bills.find(row=>row.id===id);if(!b)return;const income=transactionType(b)==='income';openModal(income?'Editar receita':'Editar despesa',`<form id="expense-edit" class="form-fields"><label>Tipo<select name="type"><option value="expense" ${!income?'selected':''}>Despesa</option><option value="income" ${income?'selected':''}>Receita</option></select></label><label>Descrição<input name="name" required value="${esc(b.name)}" maxlength="120"></label><label>Valor (R$)<input name="amount" required inputmode="decimal" value="${(b.amount/100).toFixed(2).replace('.',',')}"></label><label>Data<input name="date" type="date" value="${b.date}" required></label><label>Categoria<select name="category">${categoryOptions(b.category)}</select></label><label>Responsável<select name="payer">${owners(b.payer||'Diego')}</select></label><label class="inline"><input type="checkbox" name="paid" ${b.paid?'checked':''}>${income?'Recebida':'Paga'}</label>${b.recurring?`<p class="helper">Ocorrência ${b.occurrence} de ${b.occurrences}. Esta edição afeta somente este lançamento.</p>`:''}<div class="form-actions"><button type="button" id="expense-delete">Excluir lançamento</button><button class="primary">Salvar lançamento</button></div></form>`);$('#expense-edit').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),amount=Math.round(Number(String(f.get('amount')).replace(',','.'))*100);if(!f.get('name').trim()||!Number.isFinite(amount)||amount<=0)return;commit(()=>Object.assign(b,{name:f.get('name').trim(),amount,date:f.get('date'),category:f.get('category'),payer:f.get('payer'),type:f.get('type'),paid:f.has('paid')}),'Lançamento atualizado.');$('#dialog').close()};$('#expense-delete').onclick=()=>{commit(()=>state.bills=state.bills.filter(row=>row.id!==id),'Lançamento removido.');$('#dialog').close()}};
const bindBeforeFinance=bind;bind=function(){bindBeforeFinance();document.querySelectorAll('[data-settle]').forEach(button=>button.onclick=()=>{const row=state.bills.find(item=>item.id===button.dataset.settle);commit(()=>row.paid=true,transactionType(row)==='income'?'Receita recebida.':'Despesa paga.')})};
render();
function downloadLocalData(){try{const payload={format:'casa-prototype-v1',exportedAt:new Date().toISOString(),state:structuredClone(state)},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='casa-prototype-v1.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0);toast('Dados exportados.')}catch{toast('Não foi possível exportar os dados.')}}
const settingsWithExport=settingsModal;settingsModal=function(){settingsWithExport();const form=$('#settings-form');if(!form)return;const actions=form.querySelector('.form-actions');if(!actions)return;const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent='Exportar dados';button.addEventListener('click',downloadLocalData);actions.append(button)};
